import{_ as t}from"./chunks/show_rankings.jyDr3-70.js";import{_ as r}from"./chunks/episode_rankings.CNnrEjpM.js";import{_ as a,c as s,b as o,a0 as i}from"./chunks/framework.DZ_FiXNr.js";const w=JSON.parse('{"title":"Rankings","description":"Compare search positions for the keywords you already track. Rankings brings the show and episode views together, so you can check whether a phrase finds your whole podcast, particular episodes, or both.","frontmatter":{},"headers":[],"relativePath":"features/rankings.md","filePath":"features/rankings.md"}'),n={name:"features/rankings.md"};function h(d,e,g,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="rankings" tabindex="-1">Rankings <a class="header-anchor" href="#rankings" aria-label="Permalink to &quot;Rankings&quot;">​</a></h1><p>Compare search positions for the keywords you already track. <strong>Rankings</strong> brings the show and episode views together, so you can check whether a phrase finds your whole podcast, particular episodes, or both.</p><p><strong>To access:</strong> <strong>Search Visibility → Rankings</strong>, then select <strong>Show</strong> or <strong>Episodes</strong>. These are modes of one tab, rather than separate top-level tabs.</p><p><a href="/images/show_rankings.webp" title="Open screenshot at full size"><img src="'+t+'" alt="Rankings in Show mode with the Show and Episodes switch"></a></p><h2 id="choose-the-right-view" tabindex="-1">Choose the right view <a class="header-anchor" href="#choose-the-right-view" aria-label="Permalink to &quot;Choose the right view&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>What it answers</th><th>Full guide</th></tr></thead><tbody><tr><td><strong>Show</strong></td><td>Where does my podcast rank for each tracked keyword across the listening platforms?</td><td><a href="/features/show-rankings.html">Show rankings</a></td></tr><tr><td><strong>Episodes</strong></td><td>Which episodes rank for each tracked keyword on Apple Podcasts and Spotify?</td><td><a href="/features/episode-rankings.html">Episode rankings</a></td></tr></tbody></table><p><a href="/images/episode_rankings.webp" title="Open screenshot at full size"><img src="'+r+'" alt="Rankings in Episodes mode, showing ranking episodes for tracked keywords"></a></p><p>Start with <strong>Show</strong> to compare platforms. Switch to <strong>Episodes</strong> to see which content is carrying a term. A dash or an empty result means there is no observed rank for that item in the view; it isn&#39;t a traffic count.</p><h2 id="rankings-organic-visibility-or-tracker" tabindex="-1">Rankings, Organic Visibility, or Tracker? <a class="header-anchor" href="#rankings-organic-visibility-or-tracker" aria-label="Permalink to &quot;Rankings, Organic Visibility, or Tracker?&quot;">​</a></h2><ul><li><strong>Strategy</strong> is where you choose and assign your keywords.</li><li><strong>Organic Visibility</strong> discovers terms your show or episodes already rank for, including terms you haven&#39;t chosen to track.</li><li><strong>Rankings</strong> compares positions for your tracked terms in <strong>Show</strong> or <strong>Episodes</strong> mode.</li><li><strong>Tracker</strong> follows the history of a tracked keyword, with platform, country, and timeframe filters and competitor comparisons.</li></ul><p>Use <a href="/features/keyword-strategy.html">Strategy</a> to add a missing term. Tracking a keyword doesn&#39;t assign it to the show or an episode; choose its target there when you want it to guide optimization.</p><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>The full Show and Episodes ranking views require a paid plan. Free users can use <a href="/features/keyword-tracker.html">Tracker</a> for their tracked terms and see the limited preview offered in Rankings.</p>',13)])])}const u=a(n,[["render",h]]);export{w as __pageData,u as default};
